import{_ as s,C as n,o as d,c as a,aj as e,E as r}from"./framework.js";const m=JSON.parse(`{"title":"Jobs | Development | Admin CMS","description":"Jobs run KScript / TypeScript on the Kooboo server on a schedule: configure one-time or recurring runs for sync, cache cleanup, batch notifications, etc. Task scripts run in the site's…","frontmatter":{"title":"Jobs | Development | Admin CMS","description":"Jobs run KScript / TypeScript on the Kooboo server on a schedule: configure one-time or recurring runs for sync, cache cleanup, batch notifications, etc. Task scripts run in the site's…","head":[["link",{"rel":"canonical","href":"https://docs.kooboo.com/cms/development/jobs.html"}]]},"headers":[],"relativePath":"cms/development/jobs.md","filePath":"en/cms/development/jobs.md","lastUpdated":1783042246000}`),i={name:"cms/development/jobs.md"};function l(c,t,g,h,u,p){const o=n("DocImage");return d(),a("div",null,[t[0]||(t[0]=e('<h1 id="jobs" tabindex="-1">Jobs <a class="header-anchor" href="#jobs" aria-label="Permalink to &quot;Jobs&quot;">​</a></h1><blockquote><p>Menu: <strong>Development → Jobs</strong><br> Deep link: <code>/_Admin/development/jobs?SiteId={siteGuid}</code></p></blockquote><p><strong>Jobs</strong> run <strong>KScript / TypeScript</strong> on the Kooboo server on a schedule: configure <strong>one-time</strong> or <strong>recurring</strong> runs for sync, cache cleanup, batch notifications, etc. Task scripts run in the site&#39;s server-side script context with <code>k.content</code>, <code>k.DB</code>, <code>k.mail</code>, etc. (similar to Code in <a href="./code.html">Development → Code</a>, but triggered by the scheduler, not HTTP).</p><div class="tip custom-block"><p class="custom-block-title">Permissions</p><p>View list and logs: <code>job</code> (view). <strong>Add task</strong>, edit, save, <strong>Run</strong> require <code>job·edit</code>; multi-select <strong>Delete</strong> requires <code>job·delete</code>.</p></div><div class="info custom-block"><p class="custom-block-title">Difference from module tasks and mail tasks</p><table tabindex="0"><thead><tr><th></th><th><strong>Development → Jobs</strong></th><th><strong>Module <code>module.config</code> task</strong></th><th>Mail migration, etc.</th></tr></thead><tbody><tr><td>Config</td><td>Inline Monaco script on this page</td><td><code>task</code> in module package</td><td>Other built-in admin features</td></tr><tr><td>Scope</td><td>Current site</td><td>Module context</td><td>Mail site</td></tr><tr><td>Script trigger</td><td><code>k.site.runJob</code> (see <a href="/kb-docs/api/site/job.html">k.site.runJob</a>)</td><td>Module events</td><td>—</td></tr></tbody></table><p>Scheduler runs automatically only after site is <strong>Published</strong>; when unpublished, only <strong>manual Run</strong> for debugging.</p></div><h2 id="how-to-open" tabindex="-1">How to Open <a class="header-anchor" href="#how-to-open" aria-label="Permalink to &quot;How to Open&quot;">​</a></h2><ol><li>In <a href="./../navigation.html#edit-menu">Edit Menu</a>, enable <strong>Development → Jobs</strong>.</li><li>Open <strong>Development → Jobs</strong> in the left sidebar.</li></ol>',7)),r(o,{src:"/cms/development/jobs-overview.png",alt:"Jobs page: tabs and task list",width:"1120"}),t[1]||(t[1]=e('<h2 id="tabs" tabindex="-1">Tabs <a class="header-anchor" href="#tabs" aria-label="Permalink to &quot;Tabs&quot;">​</a></h2><table tabindex="0"><thead><tr><th>Tab</th><th>Description</th></tr></thead><tbody><tr><td><strong>Task list</strong></td><td>All <code>SiteJob</code> definitions; create, edit, manual run, delete</td></tr><tr><td><strong>Completed</strong></td><td>Recent <strong>successful</strong> runs (up to ~100)</td></tr><tr><td><strong>Failed</strong></td><td>Recent <strong>failed</strong> runs</td></tr></tbody></table><p>Logs are in central <code>JobLog</code>: task name, description, run time, return message or exception stack.</p><h2 id="task-list" tabindex="-1">Task list <a class="header-anchor" href="#task-list" aria-label="Permalink to &quot;Task list&quot;">​</a></h2><h3 id="toolbar" tabindex="-1">Toolbar <a class="header-anchor" href="#toolbar" aria-label="Permalink to &quot;Toolbar&quot;">​</a></h3><table tabindex="0"><thead><tr><th>Button</th><th>Permission</th><th>Description</th></tr></thead><tbody><tr><td><strong>Add task</strong></td><td><code>job·edit</code></td><td>Open <a href="#task-edit-dialog">task edit dialog</a> (new)</td></tr></tbody></table>',6)),r(o,{src:"/cms/development/jobs-toolbar.png",alt:"Task list toolbar",width:"1120"}),t[2]||(t[2]=e('<h3 id="list-table" tabindex="-1">List table <a class="header-anchor" href="#list-table" aria-label="Permalink to &quot;List table&quot;">​</a></h3><table tabindex="0"><thead><tr><th>Column</th><th>Description</th></tr></thead><tbody><tr><td><strong>Name</strong></td><td>Unique task name; cannot rename in dialog after create</td></tr><tr><td><strong>Status</strong></td><td><strong>Running</strong> / <strong>Completed</strong> (one-time, already fired) / <strong>Enabled</strong> (<code>active</code>) / <strong>Disabled</strong></td></tr><tr><td><strong>Start time</strong></td><td>First schedule reference (UTC storage, local display)</td></tr><tr><td><strong>Repeat</strong></td><td>Whether recurring</td></tr><tr><td><strong>Interval</strong></td><td>When repeating: &quot;Every N second/minute/hour/day/week/month&quot;</td></tr><tr><td>Row <strong>Edit</strong></td><td>Open dialog to change script and schedule</td></tr><tr><td>Multi-select <strong>Run</strong></td><td>With one row selected, toolbar <strong>Run</strong> executes once async</td></tr><tr><td>Multi-select <strong>Delete</strong></td><td><code>job·delete</code></td></tr></tbody></table>',2)),r(o,{src:"/cms/development/jobs-list-table.png",alt:"Task list table",width:"1120"}),t[3]||(t[3]=e('<h3 id="task-edit-dialog" tabindex="-1">Task edit dialog <a class="header-anchor" href="#task-edit-dialog" aria-label="Permalink to &quot;Task edit dialog&quot;">​</a></h3><table tabindex="0"><thead><tr><th>Field</th><th>Description</th></tr></thead><tbody><tr><td><strong>Name</strong></td><td>Required on create, 1–50 chars, unique in site; disabled when editing</td></tr><tr><td><strong>Start time</strong></td><td>Schedule start; one-time runs once after this time when site is published</td></tr><tr><td><strong>Enable</strong></td><td><code>active</code>: scheduler skips when off; can still <strong>Run</strong> manually</td></tr><tr><td><strong>Repeat</strong></td><td>When on, loop by interval; when off, <strong>one-time</strong></td></tr><tr><td><strong>Every</strong></td><td>When repeating: <code>frequenceUnit</code> (positive int) + unit (second / minute / hour / day / week / month)</td></tr><tr><td><strong>Execution code</strong></td><td>Monaco editor, KScript; saved to <code>SiteJob.Code</code>, not a reference to <strong>Development → Code</strong> entries</td></tr></tbody></table><p>Save via <code>Job/post</code>: new writes full model; update refreshes <code>code</code>, schedule fields, sets <code>finish</code> to <code>false</code> so one-time tasks can schedule again (adjust start time or manual run to re-trigger).</p>',3)),r(o,{src:"/cms/development/jobs-edit-dialog.png",alt:"Task edit dialog",width:"1120"}),t[4]||(t[4]=e(`<p>Example script (default comment in dialog):</p><div class="language-typescript vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">typescript</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6A737D;--shiki-dark:#6A737D;">// const log = &quot;Execute at &quot; + new Date().toString()</span></span>
<span class="line"><span style="--shiki-light:#6A737D;--shiki-dark:#6A737D;">// k.response.write(log)</span></span></code></pre></div><p>At runtime <code>JobService</code> compiles and runs this as a <strong>long task</strong>; return value or output goes to log <strong>Message</strong>.</p><h2 id="scheduling-behavior-server" tabindex="-1">Scheduling behavior (server) <a class="header-anchor" href="#scheduling-behavior-server" aria-label="Permalink to &quot;Scheduling behavior (server)&quot;">​</a></h2><p>Kooboo admin <code>JobService</code> scans in-memory tasks every second:</p><table tabindex="0"><thead><tr><th>Type</th><th>Condition</th><th>Behavior</th></tr></thead><tbody><tr><td><strong>Recurring</strong></td><td><code>active</code>, past <code>startTime</code>, interval since last run elapsed, site <strong>published</strong>, not currently running</td><td>Auto run, update last run time</td></tr><tr><td><strong>One-time</strong></td><td>Past <code>startTime</code>, not <code>finish</code>, site <strong>published</strong></td><td>Set <code>finish</code> true then run once</td></tr></tbody></table><p><strong>Manual run</strong> (list <strong>Run</strong> or <code>k.site.runJob</code>) does not require published; still async; log notes manual trigger.</p><p>Interval maps to <code>RepeatFrequence</code>: day, hour, minute, week (×7 days), month (×30 days), second.</p><h2 id="completed-failed-logs" tabindex="-1">Completed / Failed logs <a class="header-anchor" href="#completed-failed-logs" aria-label="Permalink to &quot;Completed / Failed logs&quot;">​</a></h2><p>Both tabs share columns:</p><table tabindex="0"><thead><tr><th>Column</th><th>Description</th></tr></thead><tbody><tr><td><strong>Task name</strong></td><td><code>jobName</code></td></tr><tr><td><strong>Description</strong></td><td>e.g. auto schedule, manual trigger username</td></tr><tr><td><strong>Run time</strong></td><td></td></tr><tr><td><strong>Message</strong></td><td>Success: script return; failure: exception</td></tr><tr><td><strong>Details</strong></td><td>Dialog with full <code>message</code></td></tr></tbody></table>`,11)),r(o,{src:"/cms/development/jobs-logs-completed.png",alt:"Completed log tab",width:"1120"}),t[5]||(t[5]=e('<h2 id="typical-workflow" tabindex="-1">Typical workflow <a class="header-anchor" href="#typical-workflow" aria-label="Permalink to &quot;Typical workflow&quot;">​</a></h2><ol><li><strong>Add task</strong>, name, start time, <strong>execution code</strong>.</li><li>Enable <strong>Repeat</strong> and interval for recurring; otherwise one-time.</li><li>After save, <strong>Run</strong> once and check logs (<strong>Failed</strong> tab for stack).</li><li>Ensure site <strong>published</strong>, wait for schedule, or call <code>k.site.runJob(&#39;task name&#39;)</code> from other Code.</li><li><strong>Edit</strong> to adjust logic; multi-select <strong>Delete</strong> when no longer needed.</li></ol><h2 id="related" tabindex="-1">Related <a class="header-anchor" href="#related" aria-label="Permalink to &quot;Related&quot;">​</a></h2><table tabindex="0"><thead><tr><th>Doc</th><th>Description</th></tr></thead><tbody><tr><td><a href="/kb-docs/api/site/job.html">k.site.runJob</a></td><td>Manual trigger from script</td></tr><tr><td><a href="./code.html">Code</a></td><td>Reusable Code resources (task inline script is separate)</td></tr><tr><td><a href="./modules.html">Modules</a></td><td>Module <code>task</code> and <code>k.module</code></td></tr><tr><td><a href="./../operations/site-logs.html">Operations · Operation logs</a></td><td>Site object change history (not job execution logs)</td></tr></tbody></table>',4))])}const k=s(i,[["render",l]]);export{m as __pageData,k as default};
